INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2), 'خسارة اضمحلال الشهرة:', '["بترتد لو الظروف اتحسنت","مابترتدش أبدًا","بترتد في الدخل الشامل الآخر","بترتد بعد 5 سنين"]', 1, 'IAS 36.124.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'خسارة اضمحلال الشهرة:');
INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2), 'خسارة اضمحلال وحدة توليد نقد فيها شهرة بتتوزع:', '["بالتساوي على كل الأصول","على الشهرة الأول، والباقي على الأصول بنسبة قيمها الدفترية","على الأصول الملموسة بس","على أكبر أصل"]', 1, 'IAS 36.104.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'خسارة اضمحلال وحدة توليد نقد فيها شهرة بتتوزع:');
